using System.Text.Json;

namespace Concilia.Core.Catalog;

// Writes the text of a requirement from its slots (grammar of §4 and §5 of the
// prompt). The text is always generated by the platform, never by the model.
// Port of render() in prompts/generacion_requisitos/validar_catalogo.py.
public static class CatalogRenderer
{
    public static readonly IReadOnlyDictionary<string, IReadOnlyDictionary<string, string>> Keywords =
        new Dictionary<string, IReadOnlyDictionary<string, string>>
        {
            ["es"] = new Dictionary<string, string>
            {
                ["WHEN"] = "CUANDO", ["WHILE"] = "MIENTRAS", ["IF"] = "SI", ["THEN"] = "ENTONCES", ["WHERE"] = "DONDE",
                ["SHALL"] = "DEBERÁ", ["SHOULD"] = "DEBERÍA", ["MAY"] = "PODRÁ",
                ["PROVIDE_PRE"] = "PROPORCIONAR A", ["PROVIDE_POST"] = "LA CAPACIDAD DE", ["ABLE"] = "SER CAPAZ DE", ["BE"] = "SER",
                ["C_logic"] = "SI", ["C_event"] = "EN CUANTO", ["C_time"] = "MIENTRAS", ["AND"] = "y",
            },
            ["en"] = new Dictionary<string, string>
            {
                ["WHEN"] = "WHEN", ["WHILE"] = "WHILE", ["IF"] = "IF", ["THEN"] = "THEN", ["WHERE"] = "WHERE",
                ["SHALL"] = "SHALL", ["SHOULD"] = "SHOULD", ["MAY"] = "MAY",
                ["PROVIDE_PRE"] = "PROVIDE", ["PROVIDE_POST"] = "WITH THE ABILITY TO", ["ABLE"] = "BE ABLE TO", ["BE"] = "BE",
                ["C_logic"] = "IF", ["C_event"] = "AS SOON AS", ["C_time"] = "AS LONG AS", ["AND"] = "and",
            },
        };

    // Throws KeyNotFoundException (or InvalidOperationException) if a slot the
    // template needs is missing; the validator reports that as C2.
    public static string Render(JsonElement requirement, string language)
    {
        var k = Keywords[language];
        var s = requirement.GetProperty("slots");

        if (requirement.GetProperty("notation").GetString() == "EARS")
        {
            var parts = "";
            if (Json.Truthy(s, "feature"))
                parts += $"{k["WHERE"]} {Json.Str(s, "feature")}, ";
            if (Json.Truthy(s, "states"))
                parts += $"{k["WHILE"]} {JoinList(Json.StrList(s, "states"), language)}, ";
            if (Json.Truthy(s, "trigger"))
                parts += Json.Str(s, "trigger_keyword") == "IF"
                    ? $"{k["IF"]} {Json.Str(s, "trigger")}, {k["THEN"]} "
                    : $"{k["WHEN"]} {Json.Str(s, "trigger")}, ";
            return Cap(parts + $"{Required(s, "system")} {k["SHALL"]} {Required(s, "response")}.");
        }

        var liab = k[requirement.GetProperty("obligation").GetString()!];
        var masterCondition = Json.Str(requirement, "master_condition");
        var cond = masterCondition is not null and not "none" && Json.Truthy(s, "condition")
            ? $"{k["C_" + masterCondition]} {Json.Str(s, "condition")}, "
            : "";

        if (Json.Str(requirement, "master_template") == "functional")
        {
            var mid = Json.Str(requirement, "master_activity") switch
            {
                "user_interaction" => $"{k["PROVIDE_PRE"]} {Json.Str(s, "actor")} {k["PROVIDE_POST"]} ",
                "interface" => $"{k["ABLE"]} ",
                _ => "",
            };
            var details = Json.Truthy(s, "details") ? $" {Json.Str(s, "details")}" : "";
            var output = Cap($"{cond}{Required(s, "system")} {liab} {mid}{Required(s, "process_verb")} {Required(s, "object")}{details}.");
            // In Spanish "PROPORCIONAR A el" contracts to "PROPORCIONAR AL" (R-g).
            return language == "es" ? output.Replace("PROPORCIONAR A el ", "PROPORCIONAR AL ") : output;
        }

        var q = Json.Truthy(s, "qualifying_expression") ? $"{Json.Str(s, "qualifying_expression")} " : "";
        return Cap($"{cond}{Required(s, "characteristic")} {Required(s, "subject_matter")} {liab} {k["BE"]} {q}{Required(s, "value")}.");
    }

    public static string JoinList(IReadOnlyList<string> items, string language) =>
        items.Count <= 1
            ? string.Concat(items)
            : string.Join(", ", items.Take(items.Count - 1)) + $" {Keywords[language]["AND"]} " + items[^1];

    public static string Cap(string s) => s.Length == 0 ? s : char.ToUpperInvariant(s[0]) + s[1..];

    private static string Required(JsonElement slots, string name) =>
        Json.Str(slots, name) ?? throw new KeyNotFoundException($"'{name}'");
}

// Small JsonElement helpers with Python-like semantics (a missing field or a
// null behaves like None).
internal static class Json
{
    public static string? Str(JsonElement obj, string name) =>
        obj.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : null;

    public static bool IsNull(JsonElement obj, string name) =>
        !obj.TryGetProperty(name, out var v) || v.ValueKind == JsonValueKind.Null;

    public static List<string> StrList(JsonElement obj, string name) =>
        obj.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.Array
            ? v.EnumerateArray().Where(e => e.ValueKind == JsonValueKind.String).Select(e => e.GetString()!).ToList()
            : [];

    // Python's bool(x.get(name)): false for missing, null, "" and [].
    public static bool Truthy(JsonElement obj, string name) =>
        obj.TryGetProperty(name, out var v) && v.ValueKind switch
        {
            JsonValueKind.String => v.GetString()!.Length > 0,
            JsonValueKind.Array => v.GetArrayLength() > 0,
            JsonValueKind.True => true,
            JsonValueKind.Number or JsonValueKind.Object => true,
            _ => false,
        };
}
